    def _facial_driver_state_risk_score(self, probs):
        if not probs:
            return 0.0
        weights = {
            'drowsy': 1.00,
            'yawn': 0.65,
            'phone_call': 0.20,
            'smoking': 0.15,
            'normal_focus': 0.0,
        }
        score = 0.0
        for label, weight in weights.items():
            score += self._finite_float(probs.get(label), 0.0) * weight
        return max(0.0, min(1.0, score))

