    def _profile_label(self, profile_key):
        """Return human-readable label for the given analysis profile key."""
        profiles = self._analysis_profiles().get('profiles', [])
        for p in profiles:
            if p.get('key') == profile_key:
                return p.get('label', profile_key)
        return profile_key or '기본 분석'

    def _model_options(self, baseline_state=None):
        """Return available model options.
        FN-0014: RF-Pose deprecated — hidden from UI, available only via config.
        """
        rf_available = self._rf_pipeline_available()
        rf_dual_ready = rf_available
        options = [
            {
                'key': 'rf-dual',
                'label': 'RF-Dual (Fall+Posture) 파이프라인',
                'description': f'RF 낙상 감지 + XG-Posture {self._xg_posture_class_label()} 자세 분류를 결합한 듀얼 파이프라인입니다. RF 속도 + 자세 풍부함 조합.',
                'available': rf_dual_ready,
            },
            # FN-0014 Stage A: rf-pose deprecated — UI에서 숨김
            # config에서 직접 model_type=rf-pose 지정 시에만 사용 가능
        ]
        try:
            for item in self.model_registry().get('selectable_options', []) or []:
                key = str(item.get('key') or '').strip()
                if not key or key == 'rf-dual':
                    continue
                options.append({
                    'key': key,
                    'label': item.get('label') or key,
                    'description': item.get('description') or '',
                    'available': bool(item.get('available', True)),
                    'family': item.get('family') or '',
                    'source': item.get('source') or '',
                    'model_id': item.get('model_id') or '',
                })
        except Exception:
            pass
        default_key = 'rf-dual'
        return {
            'default': default_key,
            'options': options,
        }

    def _model_option_label(self, key):
        raw_key = str(key or 'rf-dual').strip()
        if raw_key.lower().startswith('registry:'):
            model_id = raw_key.split(':', 1)[1].strip()
            try:
                item = next((it for it in self.model_registry().get('items', []) if str(it.get('model_id') or '') == model_id), None)
                if item:
                    return item.get('option_label') or item.get('label') or raw_key
            except Exception:
                pass
            return raw_key
        key = raw_key.lower()
        labels = {
            'person-feature': 'XGBoost v2 파이프라인',
            'rf-pipeline': 'RF 보조 파이프라인',
            'rf-pose': 'RF-Pose 파이프라인 (deprecated)',
            'rf-dual': 'RF-Dual (Fall+Posture) 파이프라인',
        }
        return labels.get(key, key or 'RF-Dual 파이프라인')

