    def _intake_summary(self):
        root = self._training_dir()
        summary = {'Y': 0, 'N': 0, 'total': 0, 'latest': [], 'by_date': {}, 'by_source': {'feedback': 0, 'manual': 0, 'other': 0}, 'by_target_model': {}, 'since_last_train': 0}
        latest = []
        # FN-20260406-0001: 마지막 RF-Pose 재학습 시각 로드
        rf_pose_summary = self._read_json(
            self._rf_pose_summary_path(), default={}) or {}
        last_train_at = rf_pose_summary.get('updated_at', '') or ''
        since_last_train = 0
        for label in ['Y', 'N']:
            label_dir = os.path.join(root, label)
            if os.path.isdir(label_dir) is False:
                continue
            for name in sorted(os.listdir(label_dir), reverse=True):
                if name.endswith('.json') or name.startswith('.'):
                    continue
                summary[label] += 1
                meta = self._read_json(os.path.join(label_dir, f'{name}.json'), default={}) or {}
                uploaded_at = meta.get('uploaded_at', '')
                latest.append({
                    'filename': name,
                    'label': label,
                    'uploaded_at': uploaded_at,
                    'note': meta.get('note', ''),
                    'target_model': self._normalize_training_target_model(meta.get('target_model') or ((meta.get('metadata', {}) or {}).get('target_model')) or ((meta.get('metadata', {}) or {}).get('training_target_model')) or 'rf-dual'),
                })
                # 날짜별 통계
                date_key = uploaded_at[:10] if len(uploaded_at) >= 10 else 'unknown'
                if date_key not in summary['by_date']:
                    summary['by_date'][date_key] = {'Y': 0, 'N': 0}
                summary['by_date'][date_key][label] += 1
                # 소스별 통계
                if name.startswith('feedback-'):
                    summary['by_source']['feedback'] += 1
                elif meta.get('feedback_type') == 'manual-upload':
                    summary['by_source']['manual'] += 1
                else:
                    summary['by_source']['other'] += 1
                target_model = self._normalize_training_target_model(
                    meta.get('target_model')
                    or ((meta.get('metadata', {}) or {}).get('target_model'))
                    or ((meta.get('metadata', {}) or {}).get('training_target_model'))
                    or 'rf-dual'
                )
                summary['by_target_model'][target_model] = summary['by_target_model'].get(target_model, 0) + 1
                # 마지막 재학습 이후 누적 건수
                if last_train_at and uploaded_at > last_train_at:
                    since_last_train += 1
        summary['total'] = summary['Y'] + summary['N']
        summary['latest'] = latest[:5]
        summary['since_last_train'] = since_last_train
        summary['last_train_at'] = last_train_at
        summary['target_model_total'] = sum(summary.get('by_target_model', {}).values())
        # FN-0013: Posture-class intake 통계 + hard-case 통계
        posture_stats = {}
        posture_total = 0
        for cls in self._XG_POSTURE_CLASSES:
            cls_dir = os.path.join(root, cls)
            if os.path.isdir(cls_dir):
                cnt = len([f for f in os.listdir(cls_dir) if not f.endswith('.json') and not f.startswith('.')])
                posture_stats[cls] = cnt
                posture_total += cnt
            else:
                posture_stats[cls] = 0
        summary['posture_intake'] = posture_stats
        summary['posture_intake_total'] = posture_total
        hard_dir = os.path.join(root, '_hard_cases')
        hard_count = 0
        if os.path.isdir(hard_dir):
            hard_count = len([f for f in os.listdir(hard_dir) if f.endswith('.json')])
        summary['hard_case_count'] = hard_count
        return summary

    def _retraining_health(self, baseline_summary, baseline_state):
        if baseline_state.get('ready') is False:
            return {
                'ready': False,
                'status': 'not-ready',
                'headline': '학습 요약 또는 모델 파일이 없어 추가 데이터와 재학습이 더 필요합니다.',
                'checks': [
                    {'label': '학습 모델 존재', 'status': 'pending', 'detail': '모델 파일 또는 학습 요약 파일이 아직 없습니다.'},
                    {'label': 'Holdout 평가', 'status': 'pending', 'detail': '평가 결과가 아직 없습니다.'},
                ]
            }
        evaluation = (baseline_summary.get('evaluation', {}) or {}).get('average', {}) or {}
        recall = float(evaluation.get('recall', 0.0) or 0.0)
        f1 = float(evaluation.get('f1', 0.0) or 0.0)
        precision = float(evaluation.get('precision', 0.0) or 0.0)
        accuracy = float(evaluation.get('accuracy', 0.0) or 0.0)
        checks = [
            {'label': '낙상 재현율', 'status': 'pass' if recall >= 0.85 else ('warn' if recall >= 0.7 else 'fail'), 'detail': f'recall {recall:.3f}'},
            {'label': 'F1 균형', 'status': 'pass' if f1 >= 0.8 else ('warn' if f1 >= 0.65 else 'fail'), 'detail': f'f1 {f1:.3f}'},
            {'label': '정밀도', 'status': 'pass' if precision >= 0.75 else ('warn' if precision >= 0.6 else 'fail'), 'detail': f'precision {precision:.3f}'},
            {'label': '정확도', 'status': 'pass' if accuracy >= 0.75 else ('warn' if accuracy >= 0.6 else 'fail'), 'detail': f'accuracy {accuracy:.3f}'},
        ]
        status = 'healthy'
        headline = '재학습 결과가 목표 범위에 근접합니다.'
        if any(item['status'] == 'fail' for item in checks):
            status = 'action-required'
            headline = '추가 학습 데이터 확보 또는 임계값 조정이 필요합니다.'
        elif any(item['status'] == 'warn' for item in checks):
            status = 'monitor'
            headline = '운영 전 추가 검토가 필요한 수치가 있습니다.'
        return {
            'ready': True,
            'status': status,
            'headline': headline,
            'checks': checks,
        }

    def warmup_models(self, model_type='rf-dual'):
        """Pre-load realtime models so the first live chunk does not pay cold-start cost."""
        import time as _time
        selection = self._resolve_runtime_model_selection(model_type)
        previous_selection = getattr(self, '_runtime_model_selection', None)
        self._runtime_model_selection = selection
        model_type = str(selection.get('runtime_model_type') or model_type or 'rf-dual').strip().lower()
        _t = _time.time()
        loaded = []
        errors = []
        try:
            try:
                yolo = self._get_rf_yolo_model()
                loaded.append('yolo-pose')
                try:
                    import numpy as _np
                    blank = _np.zeros((self._RF_REALTIME_YOLO_IMGSZ, self._RF_REALTIME_YOLO_IMGSZ, 3), dtype=_np.uint8)
                    yolo.predict(
                        blank,
                        imgsz=self._RF_REALTIME_YOLO_IMGSZ,
                        conf=self._RF_REALTIME_CONF_THRES,
                        device=self._get_yolo_device(),
                        verbose=False,
                    )
                    loaded.append('yolo-pose-infer')
                except Exception as infer_e:
                    errors.append({'stage': 'yolo-pose-infer', 'message': str(infer_e)})
            except Exception as e:
                errors.append({'stage': 'yolo-pose', 'message': str(e)})
            if model_type in ('rf-pose', 'auto', ''):
                try:
                    if self._rf_pose_pipeline_available():
                        self._get_rf_pose_model()
                        loaded.append('rf-pose')
                except Exception as e:
                    errors.append({'stage': 'rf-pose', 'message': str(e)})
            if model_type in ('rf-pipeline', 'rf-dual', 'auto', ''):
                try:
                    if self._rf_pipeline_available():
                        self._get_rf_model()
                        loaded.append('rf-pipeline')
                except Exception as e:
                    errors.append({'stage': 'rf-pipeline', 'message': str(e)})
            if model_type in ('rf-dual', 'auto', ''):
                try:
                    if self._rf_fall_v2_available():
                        self._get_rf_fall_v2_model()
                        loaded.append('rf-fall-v2')
                except Exception as e:
                    errors.append({'stage': 'rf-fall-v2', 'message': str(e)})
                try:
                    if self._xg_posture_available():
                        self._get_xg_posture_model()
                        loaded.append('xg-posture')
                except Exception as e:
                    errors.append({'stage': 'xg-posture', 'message': str(e)})
                # Warm the conditional lower-body occlusion helper before the first realtime chunk.
                try:
                    if self._xg_posture_occlusion_aux_available():
                        self._get_xg_posture_occlusion_aux_model()
                        loaded.append('xg-posture-occlusion-aux')
                except Exception as e:
                    errors.append({'stage': 'xg-posture-occlusion-aux', 'message': str(e)})
                try:
                    if self._facial_aux_available():
                        self._get_facial_cascade('haarcascade_eye.xml')
                        self._get_facial_cascade('haarcascade_smile.xml')
                        warm_emotion = os.environ.get('FACIAL_AUX_WARM_EMOTION', 'true').lower() not in ('0', 'false', 'no')
                        warm_driver = os.environ.get('FACIAL_AUX_WARM_DRIVER', 'true').lower() not in ('0', 'false', 'no')
                        if warm_emotion and self._get_facial_aihub82_model() is not None:
                            loaded.append('facial-state-aihub82')
                        elif warm_emotion and self._get_facial_emotion_session() is not None:
                            loaded.append('facial-state-ferplus')
                        else:
                            loaded.append('facial-state-face-only')
                        if warm_driver and self._get_facial_driver_state_model() is not None:
                            loaded.append('facial-state-aihub173-driver')
                except Exception as e:
                    errors.append({'stage': 'facial-state-aux', 'message': str(e)})
            return {
                'warmed_up': loaded,
                'elapsed_ms': round((_time.time() - _t) * 1000),
                'errors': errors,
                'selected_model_version': selection if selection.get('model_id') else {},
                'posture_occlusion_aux_available': self._xg_posture_occlusion_aux_available(),
                'facial_state_aux_available': self._facial_aux_available(),
                'facial_emotion_model_path': self._facial_emotion_model_path(),
            }
        finally:
            self._runtime_model_selection = previous_selection

    def _rt_cache_file(self, session_id):
        safe = ''.join(ch for ch in str(session_id or 'default') if ch.isalnum() or ch in ['-', '_'])[:80] or 'default'
        return os.path.join('/tmp', f'wiz_rt_cache_{safe}.json')

    def _load_rt_session_cache(self, session_id):
        path = self._rt_cache_file(session_id)
        try:
            with open(path, 'r') as f:
                return json.load(f)
        except Exception:
            return None

    def _save_rt_session_cache(self, session_id, payload):
        path = self._rt_cache_file(session_id)
        try:
            with open(path, 'w') as f:
                json.dump(payload or {}, f, ensure_ascii=False)
        except Exception:
            pass

    def _clear_rt_session_cache(self, session_id):
        path = self._rt_cache_file(session_id)
        try:
            if os.path.exists(path):
                os.remove(path)
        except Exception:
            pass

    def _latest_xg_fall_eval_summary(self):
        import glob

        report_dir = self._project_abspath('storage', 'training', 'fall-detection', 'evaluation')
        report_paths = sorted(glob.glob(os.path.join(report_dir, 'eval_xg-fall_*.json')))
        if len(report_paths) == 0:
            return None
        latest_path = report_paths[-1]
        report = self._read_json(latest_path, default={}) or {}
        xg_fall = ((report.get('models', {}) or {}).get('xg_fall', {}) or {})
        failure_report = (xg_fall.get('failure_report', {}) or {})
        return {
            'timestamp': report.get('timestamp', ''),
            'report_path': self._project_relative_path(latest_path),
            'metrics': xg_fall.get('metrics', {}) or {},
            'thresholds': xg_fall.get('thresholds', {}) or {},
            'band_counts': failure_report.get('band_counts', {}) or {},
            'false_negative_count': int(failure_report.get('false_negative_count', 0) or 0),
            'false_positive_count': int(failure_report.get('false_positive_count', 0) or 0),
            'suspected_actual_fall_count': int(failure_report.get('suspected_actual_fall_count', 0) or 0),
            'suspected_actual_nonfall_count': int(failure_report.get('suspected_actual_nonfall_count', 0) or 0),
            'suspected_actual_falls': (failure_report.get('suspected_actual_falls', []) or [])[:5],
            'suspected_actual_nonfalls': (failure_report.get('suspected_actual_nonfalls', []) or [])[:5],
        }

    def prototype_info(self):
        now = time.time()
        cached = self.__class__._prototype_info_cache
